export function daysSince(dateISO: string, now = Date.now()): number {
  const t = new Date(dateISO + 'T00:00:00Z').getTime();
  return Math.max(0, Math.round((now - t) / 86400000));
}

/** NEW badge window: components created within the last 7 days (upstream rule). */
export function isNew(createdAt: string, now = Date.now()): boolean {
  return daysSince(createdAt, now) <= 7;
}

